function finalCapital(k: number, w: number, profits: number[], capital: number[]): number {
  const used = new Array(profits.length).fill(false);
  for (let round = 0; round < k; round++) {
    let best = -1;
    for (let i = 0; i < profits.length; i++)
      if (!used[i] && capital[i] <= w && (best === -1 || profits[i] > profits[best])) best = i;
    if (best === -1) break;
    used[best] = true;
    w += profits[best];
  }
  return w;
}

