class MaxHeap {
  private a: number[] = [];
  get size() { return this.a.length; }
  push(v: number) {
    const a = this.a; a.push(v);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p] >= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]]; i = p;
    }
  }
  pop(): number {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l] > a[m]) m = l;
        if (r < a.length && a[r] > a[m]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]]; i = m;
      }
    }
    return top;
  }
}

function finalCapital(k: number, w: number, profits: number[], capital: number[]): number {
  const order = profits.map((_, i) => i).sort((x, y) => capital[x] - capital[y]);
  const heap = new MaxHeap();
  let p = 0;
  for (let round = 0; round < k; round++) {
    while (p < order.length && capital[order[p]] <= w) heap.push(profits[order[p++]]);
    if (heap.size === 0) break;
    w += heap.pop();
  }
  return w;
}

